      "status": "passed",
      "steps": [
        {"action": "m1 library row (b1-board-structure.json VAL-BOARD-002)", "expected": "name/date/events only", "observed": "library-name observatory-v1, library-date 2026-10-23, library-events 1279, no cost/waste/cycle column"},
