    "Panel header shows Events 2394 (includes turn.usage) while the library shows 1279; matches m1 (library excludes turn.usage)."
  ]
}
EOF
cat > $D/b-export.verdict.json <<EOF
{"assertion_ids":["VAL-METRIC-012","VAL-METRIC-020","VAL-CROSS-009"],"result":{"VAL-METRIC-012":"passed","VAL-METRIC-020":"passed","VAL-CROSS-009":"passed"},"evidence_path":"$E/","model":"claude-sonnet-5-5","started":"2026-10-30T03:32:00Z","finished":"2026-10-30T03:35:13Z"}
EOF
jq . $D/b-export.json >/dev/null && jq . $D/b-export.verdict.json >/dev/null && echo ok

